<template>
  <div class="app-container">
    <el-form :inline="true" :model="queryParams" class="mb8"><el-form-item label="状态"><el-select v-model="queryParams.status" clearable style="width: 180px"><el-option label="待导师审核" value="PENDING_MENTOR" /><el-option label="待管理员审核" value="PENDING_ADMIN" /><el-option label="待分配" value="WAIT_ALLOC" /><el-option label="已完成" value="COMPLETED" /><el-option label="已驳回" value="REJECTED" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="getList">搜索</el-button><el-button icon="Refresh" @click="resetQuery">重置</el-button></el-form-item></el-form>
    <el-alert title="管理员终审通过后可以先进入待分配，也可以在审批时直接选择流动工位；审批通过不等于已完成分配。" type="info" :closable="false" class="mb20"/>
    <el-table v-loading="loading" :data="applicationList"><el-table-column label="申请编号" prop="applicationId" width="100" /><el-table-column label="学生" prop="studentName" width="120" /><el-table-column label="申请原因" prop="reason" show-overflow-tooltip /><el-table-column label="计划日期" width="210"><template #default="{ row }">{{ row.plannedStart || '-' }} 至 {{ row.plannedEnd || '-' }}</template></el-table-column><el-table-column label="导师意见" prop="mentorComment" show-overflow-tooltip/><el-table-column label="管理员意见" prop="adminComment" show-overflow-tooltip/><el-table-column label="状态" prop="status" width="130"><template #default="{ row }"><el-tag>{{ statusText(row.status) }}</el-tag></template></el-table-column><el-table-column label="工位" prop="workstationNo" width="100" /><el-table-column label="操作" width="300"><template #default="{ row }"><template v-if="row.status === 'PENDING_MENTOR' && isMentor"><el-button link type="success" @click="review(row,'mentor','APPROVED')">同意</el-button><el-button link type="danger" @click="review(row,'mentor','REJECTED')">驳回</el-button></template><template v-if="row.status === 'PENDING_ADMIN' && isAdmin"><el-button link type="primary" @click="approveOnly(row)">仅审批通过</el-button><el-button link type="success" @click="openAdminApprove(row)">通过并分配</el-button><el-button link type="danger" @click="review(row,'admin','REJECTED')">驳回</el-button></template><el-button v-if="row.status === 'WAIT_ALLOC' && isAdmin" link type="primary" @click="openAssign(row)">分配工位</el-button></template></el-table-column></el-table>
    <el-dialog v-model="assignOpen" :title="approvalMode ? '管理员终审并分配流动工位' : '分配流动工位'" width="460px"><el-form label-width="90px"><el-form-item v-if="approvalMode" label="审批意见"><el-input v-model="adminComment" type="textarea" :rows="3" /></el-form-item><el-form-item label="流动工位"><el-select v-model="assignWorkstationId" style="width: 100%"><el-option v-for="item in availableWorkstations" :key="item.workstationId" :label="`${item.roomName || ''} / ${item.workstationNo}`" :value="item.workstationId" /></el-select></el-form-item></el-form><el-alert title="系统会再次校验学生无有效工位，且其导师名下没有空闲固定工位。" type="info" :closable="false"/><template #footer><el-button type="primary" @click="assign">确定</el-button><el-button @click="assignOpen = false">取消</el-button></template></el-dialog>
  </div>
</template>

<script setup name="GwApplication">
import { listApplication, mentorReview, adminReview, assignWorkstation } from '@/api/gongwei/application'
import { listWorkstation } from '@/api/gongwei/workstation'
import useUserStore from '@/store/modules/user'
const { proxy } = getCurrentInstance(); const userStore=useUserStore(); const isAdmin=computed(()=>userStore.roles.includes('admin')||userStore.roles.includes('college_admin')); const isMentor=computed(()=>userStore.roles.includes('mentor')&&!isAdmin.value); const loading = ref(false); const applicationList = ref([]); const queryParams = reactive({ status: undefined }); const assignOpen = ref(false); const assignWorkstationId = ref(); const assignRow = ref(); const availableWorkstations = ref([]); const approvalMode=ref(false); const adminComment=ref('')
function statusText(status) { return ({ PENDING_MENTOR: '待导师审核', PENDING_ADMIN: '待管理员审核', WAIT_ALLOC: '待分配', COMPLETED: '已完成', REJECTED: '已驳回' })[status] || status }
function getList() { loading.value = true; listApplication(queryParams).then(res => { applicationList.value = res.data || res.rows || [] }).finally(() => { loading.value = false }) }
function resetQuery() { queryParams.status = undefined; getList() }
function review(row, type, status) { const request = type === 'mentor' ? mentorReview : adminReview; const action=status==='APPROVED'?'同意':'驳回'; proxy.$modal.prompt(`请输入${action}意见`,`${type==='mentor'?'导师初审':'管理员终审'} - ${action}`,{inputPattern:/\S+/,inputErrorMessage:'审核意见不能为空'}).then(({value})=>request(row.applicationId,{status,comment:value})).then(()=>{proxy.$modal.msgSuccess(status==='APPROVED'?'审核通过':'已驳回');getList()}).catch(()=>{}) }
function approveOnly(row){proxy.$modal.prompt('请输入管理员审批意见，审批通过后申请将进入待分配状态','仅审批通过',{inputPattern:/\S+/,inputErrorMessage:'审批意见不能为空'}).then(({value})=>adminReview(row.applicationId,{status:'APPROVED',comment:value})).then(()=>{proxy.$modal.msgSuccess('审批通过，申请已进入待分配');getList()}).catch(()=>{})}
function loadAvailable(row,mode){assignRow.value=row;approvalMode.value=mode;assignWorkstationId.value=undefined;adminComment.value='';listWorkstation({workstationType:'MOBILE',status:'AVAILABLE'}).then(res=>{availableWorkstations.value=(res.data||res.rows||[]).filter(item=>item.roomStatus==='NORMAL');assignOpen.value=true})}
function openAdminApprove(row){loadAvailable(row,true)}
function openAssign(row){loadAvailable(row,false)}
function assign() { if (!assignWorkstationId.value) return proxy.$modal.msgWarning('请选择工位'); if(approvalMode.value&&!adminComment.value.trim())return proxy.$modal.msgWarning('请输入审批意见'); const action=approvalMode.value?adminReview(assignRow.value.applicationId,{status:'APPROVED',comment:adminComment.value,workstationId:assignWorkstationId.value}):assignWorkstation(assignRow.value.applicationId,assignWorkstationId.value); action.then(()=>{proxy.$modal.msgSuccess(approvalMode.value?'审批并分配成功':'分配成功');assignOpen.value=false;getList()}) }
getList()
</script>
